    ldr r5, DAT_0809d758                     @ 0809d71c 0e4d
    movs r1,#0xb    @ 0809d71e 0b21
    adds r2,r5,#0x0    @ 0809d720 2a1c
    bl check_value_in_slot_chain             @ 0809d722 92f7b5fa
