    cmp r0,#0x0                              @ 0809d730 0028
    beq LAB_0809d75c                         @ 0809d732 13d0
    movs r0,#0x1    @ 0809d734 0120
    subs r0,r0,r4    @ 0809d736 001b
    bl count_occupied_monster_zones          @ 0809d738 95f726fd
    cmp r0,#0x0                              @ 0809d73c 0028
    bne LAB_0809d75c                         @ 0809d73e 0dd1
    adds r0,r4,#0x0    @ 0809d740 201c
    adds r1,r5,#0x0    @ 0809d742 291c
    bl enqueue_equip_zone_sprite_by_side     @ 0809d744 aaf7ceff
    adds r0,r4,#0x0    @ 0809d748 201c
    adds r1,r5,#0x0    @ 0809d74a 291c
    movs r2,#0x5    @ 0809d74c 0522
    movs r3,#0x0    @ 0809d74e 0023
